toolScript:
let isRunning = false;
        let timer = null;
        let audioCtx = null;
        const target = document.getElementById('flash-target');
        const light = document.getElementById('status-light');
        const count = document.getElementById('countdown');
        const btnText = document.getElementById('btn-text');
        const btnIcon = document.getElementById('btn-icon');
        function toggleSync() {
            if (isRunning) {
                stop();
            } else {
                start();
            }
        }
        function start() {
            if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
            isRunning = true;
            btnText.innerText = "STOP CALIBRATION";
            btnIcon.innerHTML = '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 10a1 1 0 011-1h4a1 1 0 011 1v4a1 1 0 01-1 1h-4a1 1 0 01-1-1v-4z"></path>';
            light.classList.replace('bg-red-500', 'bg-emerald-500');
            light.classList.add('animate-pulse');
            const interval = parseInt(document.getElementById('interval').value);
            loop(interval);
        }
        function stop() {
            isRunning = false;
            clearTimeout(timer);
            btnText.innerText = "INITIALIZE CALIBRATION";
            btnIcon.innerHTML = '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z"></path><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path>';
            light.classList.replace('bg-emerald-500', 'bg-red-500');
            light.classList.remove('animate-pulse');
            target.classList.remove('flash-active');
            count.innerText = "READY";
            count.classList.replace('text-black/40', 'text-white/20');
        }
        function loop(ms) {
            if (!isRunning) return;
            triggerPulse();
            timer = setTimeout(() => loop(ms), ms);
        }
        function triggerPulse() {
            // Visual logic using requestAnimationFrame for paint precision
            requestAnimationFrame(() => {
                target.classList.add('flash-active');
                count.innerText = "PULSE";
                count.classList.replace('text-white/20', 'text-black/40');
                document.getElementById('pulse-indicator').innerText = "Signal Transmitted";
                document.getElementById('pulse-indicator').classList.add('text-black/60');
            });
            // Audio logic using Web Audio API for sub-millisecond precision
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            // Technical Setting: 1000Hz Sine is standard for reference tones
            osc.type = 'sine';
            osc.frequency.setValueAtTime(1000, audioCtx.currentTime);
            // Envelope: 0.1s decay to avoid speaker pops while keeping "pop" feel
            gain.gain.setValueAtTime(0.5, audioCtx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.08);
            osc.connect(gain);
            gain.connect(audioCtx.destination);
            osc.start();
            osc.stop(audioCtx.currentTime + 0.1);
            // Cleanup visual after short duration
            setTimeout(() => {
                target.classList.remove('flash-active');
                count.classList.replace('text-black/40', 'text-white/20');
                document.getElementById('pulse-indicator').innerText = "Waiting for Cycle...";
                document.getElementById('pulse-indicator').classList.remove('text-black/60');
            }, 100);
        }
        // --- GLOBAL SCROLL LOGIC ---
        // Ensure cleanup on page close
        window.addEventListener('beforeunload', () => {
            if (audioCtx) audioCtx.close();
        });
